function criarContador() {
  let valor = 0;            // mora na mochila desta closure
  return function () {      // função devolvida (a closure)
    valor += 1;             // enxerga 'valor' mesmo depois de criarContador terminar
    return valor;
  };
}

const contadorA = criarContador(); // mochila A
const contadorB = criarContador(); // mochila B (independente)

console.log(contadorA()); // 1
console.log(contadorA()); // 2
console.log(contadorB()); // 1  <- começou do zero, mochila própria

// Passo 1: a fábrica guarda a saudação na mochila da closure.
function criarSaudador(saudacao) {
  // Passo 2: cada cliente da fábrica ganha um contador próprio.
  let usos = 0;

  // Passo 3: a função devolvida usa os dois valores guardados.
  return function (nome) {
    if (typeof nome !== 'string') {
      throw new Error('nome precisa ser texto');
    }
    usos += 1;
    return `${saudacao}, ${nome}! (uso nº ${usos})`;
  };
}

// Passo 4: duas closures independentes, cada uma com a própria mochila.
const ola = criarSaudador('Olá');
const bomDia = criarSaudador('Bom dia');

// Passo 5: confira — saudação fixa, contador de cada uma separado.
console.log(ola('Ana'));     // Olá, Ana! (uso nº 1)
console.log(ola('Ana'));     // Olá, Ana! (uso nº 2)
console.log(bomDia('Bia'));  // Bom dia, Bia! (uso nº 1)
